//! ParentNode variadic methods use genuine native nodes and specified mutation boundaries.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str)->Value{p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap()}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><div>Main</div></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();p.set_location(&crate::navigation::address("https://parent-variadic.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}

#[test]
fn parent_node_variadic_canonical_methods_brands_descriptors_and_unscopables(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
for(var proto of [Element.prototype,DocumentFragment.prototype,Document.prototype]){for(var name of ['append','prepend','replaceChildren']){var desc=Object.getOwnPropertyDescriptor(proto,name);if(!desc||typeof desc.value!=='function'||desc.value.name!==name||desc.value.length!==0||!desc.writable||!desc.enumerable||!desc.configurable)throw 'ParentNode canonical descriptor';var blocked=Object.getOwnPropertyDescriptor(proto,Symbol.unscopables);if(!blocked||blocked.writable||!blocked.configurable||blocked.enumerable||Object.getPrototypeOf(blocked.value)!==null||blocked.value[name]!==true)throw 'ParentNode unscopables';}}
var calls=0,arg={toString:function(){calls++;return 'text';}},append=Element.prototype.append;for(var bad of [{},window,document.createTextNode('x'),document.createComment('x'),document.createAttribute('x')]){var error;try{append.call(bad,arg);}catch(e){error=e;}if(!(error instanceof TypeError)||calls)throw 'native parent brand before conversion';}var node=document.createElement('div');if(node.append()!==undefined||node.prepend()!==undefined||node.replaceChildren()!==undefined||node.childNodes.length)throw 'empty variadic calls';
"#);}
#[test]
fn parent_node_variadic_order_duplicate_aliases_fragments_and_exact_text_nodes(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
if(typeof Element.prototype.append!=='function')throw 'missing ParentNode append';for(var owner of [document,new Document(),document.implementation.createHTMLDocument('inert'),document.createElement('template').content.ownerDocument]){var host=owner.createElement('div'),a=owner.createElement('a'),b=owner.createElement('b'),c=owner.createElement('i');host.appendChild(a);host.appendChild(b);host.appendChild(c);host.append(a,'x',b,a);if(host.childNodes.length!==4||host.childNodes[0]!==c||host.childNodes[1].nodeType!==3||host.childNodes[1].data!=='x'||host.childNodes[2]!==b||host.childNodes[3]!==a)throw 'append duplicate moves';host.prepend(a,'Y',a);if(host.childNodes.length!==5||host.firstChild.data!=='Y'||host.childNodes[1]!==a||host.childNodes[2]!==c||host.lastChild!==b)throw 'prepend duplicate moves';var fragment=owner.createDocumentFragment(),leaf=owner.createElement('span');fragment.append('F',leaf);host.append(fragment);if(fragment.firstChild!==null||host.lastChild!==leaf||leaf.ownerDocument!==owner)throw 'native fragment expansion';host.prepend('A'+String.fromCharCode(55296)+'Z');if(host.firstChild.ownerDocument!==owner||host.firstChild.data.length!==3||host.firstChild.data.charCodeAt(1)!==55296)throw 'exact native text';host.append(null,undefined,false,12);if(host.childNodes[host.childNodes.length-4].data!=='null'||host.childNodes[host.childNodes.length-3].data!=='undefined'||host.childNodes[host.childNodes.length-2].data!=='false'||host.lastChild.data!=='12')throw 'DOMString union fallback';}
"#);}
#[test]
fn parent_node_variadic_converts_all_arguments_once_before_native_algorithm_and_ignores_author_shadows(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
if(typeof Element.prototype.append!=='function')throw 'missing ParentNode append';var host=document.createElement('div'),source=document.createElement('div'),a=document.createElement('b'),watch=new MutationObserver(function(){});source.appendChild(a);watch.observe(source,{childList:true});var marker={},log='',one={toString:function(){log+='1';return 'one';}},two={toString:function(){log+='2';throw marker;}};var caught;try{host.append(a,one,two);}catch(e){caught=e;}if(caught!==marker||log!=='12'||a.parentNode!==source||host.firstChild!==null||watch.takeRecords().length)throw 'binding conversions before native staging';a.toString=function(){throw 'genuine Node converted';};host.appendChild=function(){throw 'author appendChild';};host.insertBefore=function(){throw 'author insertBefore';};Object.defineProperty(host,'ownerDocument',{get:function(){throw 'author ownerDocument';},configurable:true});host.append(a,one);if(log!=='121'||host.firstChild!==a||host.lastChild.data!=='one'||a.ownerDocument!==document)throw 'intrinsic native owner and child operations';var extra=document.createElement('i'),arg={toString:function(){Element.prototype.append.call(host,extra);return 'front';}};host.prepend(arg);if(host.firstChild.data!=='front'||host.lastChild!==extra)throw 'prepend observes post-conversion children';
"#);}
#[test]
fn parent_node_variadic_replace_children_aggregates_actual_records_and_updates_live_views_and_ranges(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
if(typeof Element.prototype.replaceChildren!=='function')throw 'missing ParentNode replaceChildren';for(var owner of [document,new Document(),document.createElement('template').content.ownerDocument]){var host=owner.createElement('div'),x=owner.createTextNode('old'),y=owner.createElement('i'),a=owner.createElement('b'),b=owner.createComment('new');host.appendChild(x);host.appendChild(y);var list=host.childNodes,range=owner.createRange();range.setStart(x,1);range.setEnd(x,2);var watch=new MutationObserver(function(){});watch.observe(host,{childList:true});if(host.replaceChildren('new',a,b)!==undefined)throw 'replace result';var records=watch.takeRecords();if(records.length!==1||records[0].target!==host||records[0].previousSibling!==null||records[0].nextSibling!==null||records[0].removedNodes.length!==2||records[0].removedNodes[0]!==x||records[0].removedNodes[1]!==y||records[0].addedNodes.length!==3||records[0].addedNodes[1]!==a||records[0].addedNodes[2]!==b||list.length!==3||list[0].data!=='new'||x.parentNode!==null||y.parentNode!==null||range.startContainer!==host||range.endContainer!==host||range.startOffset!==0||range.endOffset!==0)throw 'actual aggregate replacement and range';host.replaceChildren();records=watch.takeRecords();if(list.length||records.length!==1||records[0].removedNodes.length!==3||records[0].addedNodes.length)throw 'native empty replacement';watch.disconnect();}
"#);}
#[test]
fn parent_node_variadic_fragment_conversion_commits_earlier_moves_before_later_hierarchy_failure(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
if(typeof Element.prototype.append!=='function')throw 'missing ParentNode append';for(var name of ['append','prepend','replaceChildren']){var target=document.createElement('div'),old=document.createElement('span'),source=document.createElement('div'),a=document.createElement('b'),b=document.createElement('i');target.appendChild(old);source.appendChild(a);source.appendChild(b);var watch=new MutationObserver(function(){});watch.observe(source,{childList:true});var error;try{target[name](a,document,b);}catch(e){error=e;}if(!(error instanceof DOMException)||error.name!=='HierarchyRequestError'||a.parentNode===source||a.parentNode.nodeType!==11||a.parentNode.ownerDocument!==document||b.parentNode!==source||source.firstChild!==b||target.firstChild!==old||target.lastChild!==old||watch.takeRecords().length!==1)throw 'specified native staging failure boundary';error=null;try{target[name](target);}catch(e){error=e;}if(!(error instanceof DOMException)||error.name!=='HierarchyRequestError'||target.firstChild!==old)throw 'single argument hierarchy guard';}
"#);}
#[test]
fn parent_node_variadic_saved_child_method_owner_guard_precedes_author_conversion_and_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
if(typeof Element.prototype.append!=='function')throw 'missing ParentNode append';var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var child=frame.contentWindow,append=child.Element.prototype.append,host=document.createElement('div'),calls=0,arg={toString:function(){calls++;return 'saved';}};append.call(host,'borrowed');if(host.textContent!=='borrowed')throw 'borrowed canonical child parent method';
"#);p.set_location(&crate::navigation::address("https://other.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();let error=p.runtime.execute("append.call(host,arg)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin"),"{error}");p.set_location(&crate::navigation::address("https://parent-variadic.test/source",&crate::navigation::Location::home()).unwrap());run(&mut d,&mut f,&mut p,"if(calls||host.textContent!=='borrowed')throw 'owner guard before argument effects';host.append('fresh');if(host.textContent!=='borrowedfresh')throw 'fresh native recovery';");}
#[test]
fn parent_node_variadic_single_string_refusal_preserves_native_tree_records_ranges_and_recovers(){
 for method in ["append","prepend","replaceChildren"]{for profile in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"if(typeof Element.prototype.append!=='function')throw 'missing ParentNode append';var host=document.createElement('div'),text=document.createTextNode('old');host.appendChild(text);var watch=new MutationObserver(function(){});watch.observe(host,{childList:true});var range=document.createRange();range.setStart(text,1);range.setEnd(text,2);"#);let limit=p.state.retained_limit;p.begin_job();match profile{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())}assert!(p.runtime.execute(&format!("host.{method}('new text which needs actual native storage')"),&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());p.state.retained_limit=limit;run(&mut d,&mut f,&mut p,"if(host.firstChild!==text||host.lastChild!==text||text.data!=='old'||watch.takeRecords().length||range.startContainer!==text||range.endContainer!==text||range.startOffset!==1||range.endOffset!==2)throw 'single string admission refuses before tree mutation';host.append('fresh');if(host.textContent!=='oldfresh'||watch.takeRecords().length!==1)throw 'fresh native recovery';");}
}}

#[test]
fn parent_node_variadic_single_existing_child_and_descendant_replacement_keep_native_removal_boundaries(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
for(var owner of [document,new Document(),document.createElement('template').content.ownerDocument]){var host=owner.createElement('div'),a=owner.createElement('span'),text=owner.createTextNode('old'),x=owner.createElement('b');a.appendChild(text);host.appendChild(x);host.appendChild(a);var range=owner.createRange();range.setStart(text,1);range.setEnd(text,2);var watch=new MutationObserver(function(){});watch.observe(host,{childList:true,subtree:true});host.replaceChildren(a);var records=watch.takeRecords();if(records.length!==1||records[0].removedNodes.length!==2||records[0].addedNodes.length!==1||records[0].addedNodes[0]!==a||a.parentNode!==host||x.parentNode!==null||range.startContainer!==host||range.startOffset!==0)throw 'single current child replaceall removal';host.replaceChildren(text);records=watch.takeRecords();if(records.length!==2||records[0].target!==a||records[0].removedNodes[0]!==text||records[1].target!==host||records[1].removedNodes[0]!==a||records[1].addedNodes[0]!==text||a.firstChild!==null||host.firstChild!==text||text.parentNode!==host)throw 'single descendant replacement native source removal';watch.disconnect();}
"#);}
#[test]
fn parent_node_variadic_inert_document_replace_all_validates_current_children_as_replaced(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=new Document(),old=owner.createElement('Old'),root=owner.createElement('Root');owner.appendChild(old);var watch=new MutationObserver(function(){});watch.observe(owner,{childList:true});owner.replaceChildren(root);var records=watch.takeRecords();if(owner.documentElement!==root||old.parentNode!==null||records.length!==1||records[0].removedNodes[0]!==old||records[0].addedNodes[0]!==root)throw 'document replacing-list validity';var fragment=owner.createDocumentFragment();fragment.appendChild(owner.createElement('A'));fragment.appendChild(owner.createElement('B'));var error;try{owner.replaceChildren(fragment);}catch(e){error=e;}if(!(error instanceof DOMException)||error.name!=='HierarchyRequestError'||owner.documentElement!==root||fragment.childNodes.length!==2||watch.takeRecords().length)throw 'document invalid fragment preserves replacement boundary';owner.replaceChildren();records=watch.takeRecords();if(owner.documentElement!==null||records.length!==1||records[0].removedNodes[0]!==root)throw 'document clear sync';
"#);}
#[test]
fn parent_node_variadic_union_symbol_abrupt_fake_node_and_author_mutations_are_preserved(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var host=document.createElement('div'),source=document.createElement('div'),a=document.createElement('b');source.appendChild(a);var error;try{host.append(a,Symbol('stop'));}catch(e){error=e;}if(!(error instanceof TypeError)||a.parentNode!==source||host.firstChild!==null)throw 'symbol union throws before staging';var calls=0,fake={nodeType:1,toString:function(){calls++;host.appendChild(document.createComment('side'));return 'fake';}};host.prepend(fake);if(calls!==1||host.firstChild.nodeType!==3||host.firstChild.data!=='fake'||host.lastChild.nodeType!==8)throw 'fake Node string fallback and callback effects';var marker={},bad={toString:function(){host.appendChild(a);throw marker;}},caught;try{host.replaceChildren(bad);}catch(e){caught=e;}if(caught!==marker||a.parentNode!==host||host.lastChild!==a)throw 'author conversion effects retained';
"#);}

#[test]
fn parent_node_variadic_inert_document_prepend_uses_actual_first_child_for_doctype_validity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
for(var owner of [new Document(),document.createElement('template').content.ownerDocument]){var root=owner.createElement('Root'),dtype=owner.implementation.createDocumentType('Root','','');owner.append(root);owner.prepend(dtype);if(owner.firstChild!==dtype||owner.lastChild!==root||owner.doctype!==dtype||owner.documentElement!==root)throw 'prepend doctype before actual root';var comment=owner.createComment('first');owner.prepend(comment);if(owner.firstChild!==comment||owner.childNodes[1]!==dtype)throw 'prepend document comment';var other=owner.implementation.createDocumentType('Other','',''),error;try{owner.append(other);}catch(e){error=e;}if(!(error instanceof DOMException)||error.name!=='HierarchyRequestError'||other.parentNode!==null||owner.doctype!==dtype)throw 'append document doctype validity';}
"#);}
